/**
 * Typed json-render AST helpers shared by Canvas and app UI composition.
 * Field-binding leaves take a `FieldRef` token (not a
 * live `AppField`) and emit the field id position as a token resolved at deploy.
 *
 * A binding leaf needs the field id in two places — `__binding.aspectFieldId`
 * (resolved straight to the id) and the `record/<id>` **statePath string**. v2
 * has no id at author time, so the statePath is emitted as a structured marker
 * `{ __recordPath: <FieldRef token> }`; the Terraform emitter resolves it to a
 * `"record/${field-resource.id}"` template inside the JSON configuration.
 */
import { EdkValidationError } from "../../elementum-entity-client/errors.js";
/** Marker key the Terraform emitter flattens to a `record/<id>` statePath string. */
export const RECORD_PATH_MARKER = "__recordPath";
const NODE_KIND = "render-node";
/** Build the structured statePath marker for a field (flattened to a string at deploy). */
function recordPath(field) {
    return { [RECORD_PATH_MARKER]: field };
}
export function stack(children, props) {
    return { __nodeKind: NODE_KIND, type: "Stack", props: { ...(props ?? {}) }, children };
}
export function card(props, children) {
    return { __nodeKind: NODE_KIND, type: "Card", props: { ...props }, children };
}
export function grid(props, children) {
    return { __nodeKind: NODE_KIND, type: "Grid", props: { ...props }, children };
}
export function heading(text, props) {
    return { __nodeKind: NODE_KIND, type: "Heading", props: { text, ...(props ?? {}) } };
}
export function text(value, props) {
    return { __nodeKind: NODE_KIND, type: "Text", props: { text: value, ...(props ?? {}) } };
}
export function separator(props) {
    return { __nodeKind: NODE_KIND, type: "Separator", props: { ...(props ?? {}) } };
}
/**
 * Build a single-node `ActivityNode` element — a colored leaf rendering an
 * entity reference. Useful for the agent / automation grids in `App.toUI()`.
 */
export function activityNode(spec) {
    const props = { kind: spec.kind, name: spec.name };
    if (spec.subType != null)
        props.subType = spec.subType;
    if (spec.referenceName != null)
        props.referenceName = spec.referenceName;
    if (spec.typeLabel != null)
        props.typeLabel = spec.typeLabel;
    return { __nodeKind: NODE_KIND, type: "ActivityNode", props };
}
export const required = (message) => message ? { type: "required", message } : { type: "required" };
export const email = (message) => message ? { type: "email", message } : { type: "email" };
export const minLength = (value, message) => message ? { type: "minLength", value, message } : { type: "minLength", value };
export const maxLength = (value, message) => message ? { type: "maxLength", value, message } : { type: "maxLength", value };
/** Attach the binding marker + state path. `aspectFieldId` resolves to the id at deploy. */
function buildBindingNode(type, field, props) {
    const statePath = recordPath(field);
    return {
        __nodeKind: NODE_KIND,
        type,
        props: { ...props, name: statePath, statePath },
        __binding: { aspectFieldId: field, statePath },
    };
}
function commonProps(field, opts) {
    const props = { label: opts.label ?? field.name };
    if (opts.helpText != null)
        props.helpText = opts.helpText;
    if (opts.checks != null && opts.checks.length > 0)
        props.checks = opts.checks;
    return props;
}
/** Bind a scalar field (TEXT/NUMBER/DECIMAL/DATE/DATETIME/USER_ID/GROUP_ID) to an `Input`. */
export function inputFor(field, opts = {}) {
    const inferred = field.fieldType === "NUMBER" || field.fieldType === "DECIMAL"
        ? "number"
        : field.fieldType === "DATE"
            ? "date"
            : field.fieldType === "DATETIME"
                ? "datetime-local"
                : "text";
    const props = commonProps(field, opts);
    props.type = opts.type ?? inferred;
    if (opts.placeholder != null)
        props.placeholder = opts.placeholder;
    return buildBindingNode("Input", field, props);
}
/** Bind a TEXT/RICH_TEXT field to a `Textarea`. */
export function textareaFor(field, opts = {}) {
    const props = commonProps(field, opts);
    if (opts.placeholder != null)
        props.placeholder = opts.placeholder;
    if (opts.rows != null)
        props.rows = opts.rows;
    return buildBindingNode("Textarea", field, props);
}
/** Bind a PICKLIST/MULTI_PICKLIST field to a `Select` (options fetched at render time unless given). */
export function selectFor(field, opts = {}) {
    const props = commonProps(field, opts);
    if (opts.placeholder != null)
        props.placeholder = opts.placeholder;
    if (opts.options != null)
        props.options = opts.options;
    return buildBindingNode("Select", field, props);
}
/** Bind a BOOLEAN field to a `Switch`. */
export function switchFor(field, opts = {}) {
    return buildBindingNode("Switch", field, commonProps(field, opts));
}
/** Bind a BOOLEAN field to a `Checkbox`. */
export function checkboxFor(field, opts = {}) {
    return buildBindingNode("Checkbox", field, commonProps(field, opts));
}
/** Bind any binding-eligible field to the component best fitting its declared type. */
export function fieldFor(field, opts = {}) {
    switch (field.fieldType) {
        case "PICKLIST":
        case "MULTI_PICKLIST":
            return selectFor(field, opts);
        case "RICH_TEXT":
            return textareaFor(field, opts);
        case "BOOLEAN":
            return switchFor(field, opts);
        case "TEXT":
        case "NUMBER":
        case "DECIMAL":
        case "DATE":
        case "DATETIME":
        case "USER_ID":
        case "GROUP_ID":
            return inputFor(field, opts);
        default:
            throw new EdkValidationError(`fieldFor: field "${field.name}" has type "${field.fieldType}" which no binding helper supports. ` +
                `Use a layout helper (heading / text / separator) or a specific binding helper.`);
    }
}
export function isRenderNode(value) {
    return (typeof value === "object" &&
        value !== null &&
        value.__nodeKind === NODE_KIND);
}
function uniqueElementId(candidate, used) {
    if (!used.has(candidate))
        return candidate;
    let suffix = 2;
    while (used.has(`${candidate}_${suffix}`))
        suffix++;
    return `${candidate}_${suffix}`;
}
/** Walk the AST depth-first → flat `{ root, elements }`; `visit` collects bindings. */
export function serializeRenderTree(layout, visit) {
    if (!isRenderNode(layout)) {
        throw new EdkValidationError(`serializeRenderTree: \`layout\` must be a RenderNode from the catalog helpers (card, stack, inputFor, ...).`);
    }
    const elements = {};
    const usedIds = new Set();
    const walk = (node, path) => {
        const id = uniqueElementId(path, usedIds);
        usedIds.add(id);
        let childIds;
        if (node.children && node.children.length > 0) {
            childIds = node.children.map((child, index) => walk(child, `${path}.${index}`));
        }
        elements[id] = { type: node.type, props: node.props, ...(childIds ? { children: childIds } : {}) };
        visit?.(node, id);
        return id;
    };
    const root = walk(layout, "root");
    return { root, elements };
}
